/*
Чтобы поле участвовало в валидации добавляем атрибут data-required
Особые проверки:
data-required="email" - вадидация E-mail

Чтобы поле валидировалось при потере фокуса, 
к атрибуту data-required добавляем атрибут data-validate

Чтобы вывести текст ошибки, нужно указать его в атрибуте data-error 
*/

// Работа с полями формы. Добавление классов, работа с placeholder
function formFieldsInit() {
  const formFields = document.querySelectorAll('input[placeholder],textarea[placeholder]');
  document.body.addEventListener("focusin", function (e) {
    const targetElement = e.target;
    if (targetElement.tagName === 'INPUT' || targetElement.tagName === 'TEXTAREA') {
      if (targetElement.dataset.placeholder) {
        targetElement.placeholder = '';
      }
      targetElement.classList.add('_form-focus');
      targetElement.parentElement.classList.add('_form-focus');
      formValidate.removeError(targetElement);
    }
  });
  // Снятие ошибки чекбокса при отметке (клик по label не даёт focus на скрытый input)
  document.body.addEventListener('change', function (e) {
    const target = e.target;
    if (target.type === 'checkbox' && target.hasAttribute('data-required') && target.checked) {
      formValidate.removeError(target);
    }
  });

  // #user-phone плюс поля с data-phone-mask: форма на странице может быть не одна
  var phoneInputs = document.querySelectorAll('#user-phone, input[data-phone-mask]');
  if (phoneInputs.length && typeof SimplePhoneMask !== 'undefined') {
    phoneInputs.forEach(function (phoneInput) {
      if (!phoneInput.id) return;
      var phoneMask = new SimplePhoneMask('#' + phoneInput.id, {
        countryCode: 'RU',
        showFlag: true,
        allowCountrySelect: true
      });
      phoneInput.phoneMaskInstance = phoneMask;
    });
  }
}
// Валидация форм
let formValidate = {
  getErrors(form) {
    let error = 0;
    let formRequiredItems = form.querySelectorAll('*[data-required]');
    if (formRequiredItems.length) {
      formRequiredItems.forEach(formRequiredItem => {
        if ((formRequiredItem.offsetParent !== null || formRequiredItem.tagName === "SELECT") && !formRequiredItem.disabled) {
          error += this.validateInput(formRequiredItem);
        }
      });
    }
    return error;
  },
  validateInput(formRequiredItem) {
    let error = 0;
    if (formRequiredItem.dataset.required === "email") {
      formRequiredItem.value = formRequiredItem.value.replace(" ", "");
      if (this.emailTest(formRequiredItem)) {
        this.addError(formRequiredItem);
        error++;
      } else {
        this.removeError(formRequiredItem);
      }
    } else if (formRequiredItem.dataset.required === "name") {
      formRequiredItem.value = formRequiredItem.value.replace(/[^А-Яа-яёA-Za-z- ]/g, '');
      if (formRequiredItem.value.trim().length < 3) {
        this.addError(formRequiredItem);
        error++;
        formRequiredItem.parentElement.querySelector('.form__error').innerHTML = "Минимальная длинна 3 символа";
      } else {
        this.removeError(formRequiredItem);
      }
    } else if (formRequiredItem.dataset.required === "tel") {
      let phoneMaskInstance = formRequiredItem.phoneMaskInstance;
      if (phoneMaskInstance) {
        if (phoneMaskInstance.currentCountry.name === 'Другая страна') {
          this.removeError(formRequiredItem);
        } else {
          let digits = formRequiredItem.value.replace(/\D/g, '');
          let maskDigitsCount = (phoneMaskInstance.maskPattern.match(/_/g) || []).length;
          let expectedDigits = phoneMaskInstance.countryCode.length + maskDigitsCount;
          if (digits.length !== expectedDigits) {
            this.addError(formRequiredItem);
            error++;
            this.getErrorContainer(formRequiredItem).querySelector('.form__error').innerHTML = "Укажите номер полностью";
          } else {
            this.removeError(formRequiredItem);
          }
        }
      } else if (formRequiredItem.value.trim().length < 17) {
        this.addError(formRequiredItem);
        error++;
        this.getErrorContainer(formRequiredItem).querySelector('.form__error').innerHTML = "Минимальная длинна 10 символов";
      } else {
        this.removeError(formRequiredItem);
      }
    } else if (formRequiredItem.dataset.required === "number") {
      let numValue = parseInt(formRequiredItem.value, 10);
      if (!formRequiredItem.value.trim() || isNaN(numValue) || numValue <= 0) {
        this.addError(formRequiredItem);
        error++;
      } else {
        this.removeError(formRequiredItem);
      }
    } else if (formRequiredItem.type === "checkbox" && !formRequiredItem.checked) {
      this.addError(formRequiredItem);
      error++;
    } else {
      if (!formRequiredItem.value.trim()) {
        this.addError(formRequiredItem);
        error++;
      } else {
        this.removeError(formRequiredItem);
      }
    }
    return error;
  },
  getErrorContainer(formRequiredItem) {
    return formRequiredItem.closest('.item-field') || formRequiredItem.parentElement;
  },
  addError(formRequiredItem) {
    formRequiredItem.classList.add('_form-error');
    let errorContainer = this.getErrorContainer(formRequiredItem);
    errorContainer.classList.add('_form-error');
    errorContainer.classList.remove('_check-focus');
    let inputError = errorContainer.querySelector('.form__error');
    if (inputError) errorContainer.removeChild(inputError);
    if (formRequiredItem.dataset.error) {
      errorContainer.insertAdjacentHTML('beforeend', `<span class="form__error">${formRequiredItem.dataset.error}</span>`);
    }
  },
  removeError(formRequiredItem) {
    formRequiredItem.classList.remove('_form-error');
    let errorContainer = this.getErrorContainer(formRequiredItem);
    errorContainer.classList.remove('_form-error');
    let inputError = errorContainer.querySelector('.form__error');
    if (inputError) errorContainer.removeChild(inputError);
  },
  formClean(form) {
    form.reset();
    setTimeout(() => {
      let inputs = form.querySelectorAll('input:not([type="hidden"]):not([type="checkbox"]),textarea');
      for (let index = 0; index < inputs.length; index++) {
        const el = inputs[index];
        el.parentElement.classList.remove('_form-focus');
        el.classList.remove('_form-focus');
        formValidate.removeError(el);
        if (el.phoneMaskInstance) {
          el.value = '+' + el.phoneMaskInstance.countryCode;
        } else {
          el.value = '';
        }
      }
      let checkboxes = form.querySelectorAll('.checkbox__input');
      if (checkboxes.length > 0) {
        for (let index = 0; index < checkboxes.length; index++) {
          const checkbox = checkboxes[index];
          checkbox.checked = false;
        }
      }
      if (formsModules.selectModule) {
        let selects = form.querySelectorAll('.select');
        if (selects.length) {
          for (let index = 0; index < selects.length; index++) {
            const select = selects[index].querySelector('select');
            formsModules.selectModule.selectBuild(select);
          }
        }
      }
    }, 0);
  },
  emailTest(formRequiredItem) {
    return !/^\w+([\.-]?\w+)*@\w+([\.-]?\w+)*(\.\w{2,8})+$/.test(formRequiredItem.value);
  }
};

// Ограничение ввода цифровых символов и символов более 500
document.addEventListener('input', function (e) {
  const input = e.target;
  if (input.dataset.required === "name") {
    input.value = input.value.replace(/[^А-Яа-яёA-Za-z- ]/g, '');
  }
  if (input.value.length > 500) {
    input.value = input.value.slice(0, 50);
  }
});

/* Отправка форм */
function formSubmit(validate) {
  const forms = document.forms;
  if (forms.length) {
    for (const form of forms) {
      form.addEventListener('submit', function (e) {
        const form = e.target;
        formSubmitAction(form, e);
      });
      form.addEventListener('reset', function (e) {
        const form = e.target;
        formValidate.formClean(form);
      });
    }
  }
  async function formSubmitAction(form, e) {
    const error = validate ? formValidate.getErrors(form) : 0;
    if (error === 0) {
      const popupMessage = form.dataset.popupMessage;
      const ajax = form.hasAttribute('data-ajax');
      if (ajax) {
        e.preventDefault();
        const formAction = form.getAttribute('action') ? form.getAttribute('action').trim() : '#';
        const formMethod = form.getAttribute('method') ? form.getAttribute('method').trim() : 'GET';
        const formData = new FormData(form);

        // BEGIN ->ПОДКИДЫВАЮ ДАННЫЕ ОБ АКТИВНОЙ ДАТЕ В МУЛЬТЕДАТЕ, ЕСЛИ ОНА ЕСТЬ
        var curentDate = document.querySelector('.multi-date__click.active');
        if (curentDate) formData.append('datetime', curentDate.getAttribute('data-date-msk'));
        // END ->ПОДКИДЫВАЮ ДАННЫЕ ОБ АКТИВНОЙ ДАТЕ В МУЛЬТЕДАТЕ, ЕСЛИ ОНА ЕСТЬ 

        // ============================================================
        // CAPTCHA: получить токен, если форма защищена капчей
        // Добавить на форму: data-captcha="true" + контейнер .smart-captcha
        // Работает автоматически — формы без капчи не затрагиваются
        //
        // Sentinel-значение "CAPTCHA_UNAVAILABLE":
        // JS всегда явно заполняет поле smart-token — либо реальным токеном,
        // либо sentinel-строкой если Яндекс был недоступен.
        // PHP отличает это от прямого POST-запроса бота (поле пустое/отсутствует).
        // ============================================================
        const CAPTCHA_SENTINEL = 'CAPTCHA_UNAVAILABLE';
        if (form.captchaAPI) {
          const captchaAPI = form.captchaAPI;
          if (!captchaAPI.isExecuted() || !captchaAPI.getToken()) {
            // Ждём токен с таймаутом 10 сек
            const captchaTimeout = new Promise(resolve => setTimeout(() => {
              console.warn('[Captcha] Таймаут ожидания токена — отправляем sentinel');
              resolve(null);
            }, 10000));
            const captchaToken = new Promise(resolve => captchaAPI.execute(resolve));
            await Promise.race([captchaToken, captchaTimeout]);
          }
          // Если токена нет — отправляем sentinel, не пустую строку.
          // PHP знает: sentinel = Яндекс был недоступен = fail open.
          // Пустое/отсутствующее поле = бот = блокировать.
          formData.set('smart-token', captchaAPI.getToken() || CAPTCHA_SENTINEL);
        }
        // ============================================================

        form.classList.add('_sending');
        try {
          const response = await fetch('/ajax/' + formAction, {
            method: formMethod,
            body: formData
          });
          const popupItem = initPopups();
          const commonErrorPopupId = '#popup-error';
          if (response.ok) {
            let responseResult = false;
            form.classList.remove('_sending');
            if (form.captchaAPI) form.captchaAPI.reset();
            try {
              responseResult = await response.json();
            } catch (e) {
              popupItem.open(commonErrorPopupId);
              formValidate.formClean(form);
              return;
            }
            if (popupMessage && responseResult.result) {
              popupItem.open(popupMessage); // Открываем попап, используя значение атрибута data-popup-message
            } else {
              popupItem.open(commonErrorPopupId);
            }
            formValidate.formClean(form);
          } else {
            form.classList.remove('_sending');
            if (form.captchaAPI) form.captchaAPI.reset();
            popupItem.open(commonErrorPopupId);
            formValidate.formClean(form);
          }
        } catch {
          const popupItem = initPopups();
          const commonErrorPopupId = '#popup-error';
          popupItem.open(commonErrorPopupId);
          formValidate.formClean(form);
        } finally {
          form.classList.remove('_sending');
          if (form.captchaAPI) form.captchaAPI.reset();
        }
      }
    } else {
      e.preventDefault();
      const formError = form.querySelector('._form-error');
      if (formError && form.hasAttribute('data-goto-error')) {
        gotoblock_gotoBlock(formError, true, 1000);
      }
    }
  }
}
