// Map zoom scheme
function initSchemeMapZoomAndDrag() {
  const schemeContainer = document.querySelector('.scheme-map__map-svg');
  const schemeImage = schemeContainer?.querySelector('svg');
  const schemeBtnZoomIn = document.querySelector('.control-scheme__btn_plus');
  const schemeBtnZoomOut = document.querySelector('.control-scheme__btn_minus');
  if (!schemeContainer || !schemeImage || !schemeBtnZoomIn || !schemeBtnZoomOut) return;
  const schemeMaxStep = 5;
  const schemeMinStep = 1;
  let schemeStep = 1;
  const schemeScaleStep = 0.2;
  const baseScale = 1;
  let schemeIsDragging = false;
  let schemeStartX = 0,
    schemeStartY = 0;
  let schemeCurrentX = 0,
    schemeCurrentY = 0;
  function updateSchemeTransform() {
    const scale = baseScale + schemeScaleStep * (schemeStep - 1);
    schemeImage.style.transform = `translate(${schemeCurrentX}px, ${schemeCurrentY}px) scale(${scale})`;
    schemeImage.style.transformOrigin = 'center center';
  }
  function updateButtonsState() {
    schemeBtnZoomOut.classList.toggle('_active', schemeStep > schemeMinStep);
    schemeBtnZoomIn.classList.toggle('_disabled', schemeStep >= schemeMaxStep);
  }
  function startDrag(x, y) {
    if (schemeStep <= schemeMinStep) return;
    schemeIsDragging = true;
    schemeStartX = x - schemeCurrentX;
    schemeStartY = y - schemeCurrentY;
    schemeContainer.style.cursor = 'grabbing';
  }
  function moveDrag(x, y) {
    if (!schemeIsDragging) return;
    schemeCurrentX = x - schemeStartX;
    schemeCurrentY = y - schemeStartY;
    updateSchemeTransform();
  }
  function stopDrag() {
    if (!schemeIsDragging) return;
    schemeIsDragging = false;
    schemeContainer.style.cursor = 'grab';
  }

  // Zoom buttons
  schemeBtnZoomIn.addEventListener('click', () => {
    if (schemeStep < schemeMaxStep) {
      schemeStep++;
      updateSchemeTransform();
      updateButtonsState();
    }
  });
  schemeBtnZoomOut.addEventListener('click', () => {
    if (schemeStep > schemeMinStep) {
      schemeStep--;
      schemeCurrentX = 0;
      schemeCurrentY = 0;
      updateSchemeTransform();
      updateButtonsState();
    }
  });

  // Mouse events
  schemeContainer.addEventListener('mousedown', e => {
    startDrag(e.clientX, e.clientY);
  });
  document.addEventListener('mousemove', e => {
    moveDrag(e.clientX, e.clientY);
  });
  document.addEventListener('mouseup', stopDrag);

  // Touch events (mobile support)
  schemeContainer.addEventListener('touchstart', e => {
    if (e.touches.length === 1) {
      startDrag(e.touches[0].clientX, e.touches[0].clientY);
    }
  });
  document.addEventListener('touchmove', e => {
    if (e.touches.length === 1) {
      moveDrag(e.touches[0].clientX, e.touches[0].clientY);
    }
  }, {
    passive: false
  });
  document.addEventListener('touchend', stopDrag);
  updateButtonsState();
  updateSchemeTransform();
}
document.addEventListener('DOMContentLoaded', initSchemeMapZoomAndDrag);
