// Map zoom sector
function initMobileSectorsMapZoomAndDrag() {
  if (window.innerWidth > 1024) return;
  const container = document.querySelector('.sectors-map__box');
  const svg = container?.querySelector('svg');
  const zoomInBtn = document.querySelector('.js-sectors-plus');
  const zoomOutBtn = document.querySelector('.js-sectors-minus');
  if (!container || !svg || !zoomInBtn || !zoomOutBtn) return;
  const maxZoomStep = 5;
  const minZoomStep = 1;
  let currentZoomStep = 1;
  const scaleStep = 0.2;
  const baseScale = 1;
  let isDragging = false;
  let startX = 0,
    startY = 0;
  let offsetX = 0,
    offsetY = 0;
  function applyTransform() {
    const scale = baseScale + (currentZoomStep - 1) * scaleStep;
    svg.style.transform = `translate(${offsetX}px, ${offsetY}px) scale(${scale})`;
    svg.style.transformOrigin = 'center center';
  }
  function updateButtons() {
    zoomOutBtn.classList.toggle('_active', currentZoomStep > minZoomStep);
    zoomInBtn.classList.toggle('_disabled', currentZoomStep >= maxZoomStep);
  }
  zoomInBtn.addEventListener('click', () => {
    if (currentZoomStep < maxZoomStep) {
      currentZoomStep++;
      applyTransform();
      updateButtons();
    }
  });
  zoomOutBtn.addEventListener('click', () => {
    if (currentZoomStep > minZoomStep) {
      currentZoomStep--;
      offsetX = 0;
      offsetY = 0;
      applyTransform();
      updateButtons();
    }
  });

  // 🖱️ Drag Start
  svg.addEventListener('mousedown', e => {
    if (currentZoomStep <= minZoomStep) return;
    isDragging = true;
    startX = e.clientX - offsetX;
    startY = e.clientY - offsetY;
    container.style.cursor = 'grabbing';
    e.preventDefault();
  });

  // 🖱️ Drag Move
  document.addEventListener('mousemove', e => {
    if (!isDragging) return;
    offsetX = e.clientX - startX;
    offsetY = e.clientY - startY;
    applyTransform();
  });

  // 🖱️ Drag End
  document.addEventListener('mouseup', () => {
    if (!isDragging) return;
    isDragging = false;
    container.style.cursor = 'grab';
  });

  // touch support (📱)
  svg.addEventListener('touchstart', e => {
    if (currentZoomStep <= minZoomStep) return;
    isDragging = true;
    const touch = e.touches[0];
    startX = touch.clientX - offsetX;
    startY = touch.clientY - offsetY;
    container.style.cursor = 'grabbing';
  });
  svg.addEventListener('touchmove', e => {
    if (!isDragging) return;
    const touch = e.touches[0];
    offsetX = touch.clientX - startX;
    offsetY = touch.clientY - startY;
    applyTransform();
  });
  svg.addEventListener('touchend', () => {
    isDragging = false;
    container.style.cursor = 'grab';
  });

  // Инициализация
  container.style.cursor = 'grab';
  applyTransform();
  updateButtons();
}
document.addEventListener('DOMContentLoaded', () => {
  initMobileSectorsMapZoomAndDrag();
});
