// Подсветка блоков на карте
document.addEventListener('DOMContentLoaded', () => {
  const buttons = document.querySelectorAll('.actions-scheme__btn');
  const svg = document.querySelector('.scheme-map__map-svg svg');
  if (!svg) return;

  // Все элементы с data-color внутри SVG
  const svgBlocks = svg.querySelectorAll('[data-color]');

  // Убрать все подсветки и затемнения
  function resetSvgStyles() {
    svgBlocks.forEach(block => {
      block.classList.remove('highlight', 'dimmed');
    });
  }

  // Подсветить блоки с цветом color (например, '_red')
  function highlightBlocks(color) {
    svgBlocks.forEach(block => {
      if (block.dataset.color === color) {
        block.classList.add('highlight');
      } else {
        block.classList.remove('highlight');
      }
    });
  }

  // При клике (чек) — затемнить все кроме выбранных
  function dimExceptSelected(selectedColors) {
    svgBlocks.forEach(block => {
      if (selectedColors.includes(block.dataset.color)) {
        block.classList.remove('dimmed');
      } else {
        block.classList.add('dimmed');
      }
    });
  }
  buttons.forEach(btn => {
    const input = btn.querySelector('input[type="checkbox"]');
    const btnColorClass = Array.from(btn.classList).find(c => c.startsWith('_'));
    if (!btnColorClass || !input) return;

    // Наведение — подсвечиваем
    btn.addEventListener('mouseenter', () => {
      highlightBlocks(btnColorClass);
    });

    // Убираем подсветку при уходе мыши с кнопки
    btn.addEventListener('mouseleave', () => {
      resetSvgStyles();

      // Если есть выбранные чекбоксы, применяем затемнение к ним
      const checkedColors = Array.from(buttons).filter(b => b.querySelector('input[type="checkbox"]').checked).map(b => Array.from(b.classList).find(c => c.startsWith('_'))).filter(Boolean);
      if (checkedColors.length) {
        dimExceptSelected(checkedColors);
      }
    });

    // При клике на чекбокс — затемняем все кроме выбранных
    input.addEventListener('change', () => {
      const checkedColors = Array.from(buttons).filter(b => b.querySelector('input[type="checkbox"]').checked).map(b => Array.from(b.classList).find(c => c.startsWith('_'))).filter(Boolean);
      if (checkedColors.length) {
        dimExceptSelected(checkedColors);
      } else {
        resetSvgStyles();
      }
    });
  });
});
