// Переключение схем стадион - схема
function initSectorGroupClick() {
  const sectorGroups = document.querySelectorAll("#sector_scheme g.active");
  const sectorsBlock = document.querySelector(".map-events__sectors");
  const closeBtn = document.querySelector(".sectors-map__btn");
  const sectorScheme = document.getElementById("sector_scheme");
  if (sectorGroups.length && sectorsBlock) {
    sectorGroups.forEach(group => {
      group.addEventListener("click", () => {
        if (sectorsBlock.hasAttribute("hidden")) {
          sectorsBlock.removeAttribute("hidden");

          // Скроллим к открытому блоку
          sectorsBlock.scrollIntoView({
            behavior: "smooth",
            block: "start"
          });
        }
      });
    });
  }
  if (closeBtn && sectorsBlock && sectorScheme) {
    closeBtn.addEventListener("click", () => {
      if (!sectorsBlock.hasAttribute("hidden")) {
        sectorsBlock.setAttribute("hidden", "");

        // Скроллим обратно к схеме
        sectorScheme.scrollIntoView({
          behavior: "smooth",
          block: "start"
        });
      }
    });
  }
}
function initResponsiveSectorMap() {
  const sectorGroups = document.querySelectorAll("#sector_scheme g.active");
  const sectorsBlock = document.querySelector(".map-events__sectors");
  const closeBtn = document.querySelector(".sectors-map__btn");
  const schemeMapBtnList = document.querySelector(".scheme-map__btn-list");
  const footerListMapBtn = document.querySelector(".footer-list-map__btn");
  const mapEventsList = document.querySelector(".map-events__list");
  if (sectorGroups.length && sectorsBlock) {
    sectorGroups.forEach(group => {
      group.addEventListener("click", () => {
        if (window.innerWidth <= 1024) {
          sectorsBlock.removeAttribute("hidden");
          sectorsBlock.classList.add("_active");
        }
      });
    });
  }
  if (closeBtn && sectorsBlock) {
    closeBtn.addEventListener("click", () => {
      if (!sectorsBlock.hasAttribute("hidden")) {
        sectorsBlock.setAttribute("hidden", "");
        sectorsBlock.classList.remove("_active");
      }
    });
  }
  if (schemeMapBtnList && mapEventsList) {
    schemeMapBtnList.addEventListener("click", () => {
      if (window.innerWidth <= 1024) {
        mapEventsList.removeAttribute("hidden");
        mapEventsList.classList.add("_active");
      }
    });
  }
  if (footerListMapBtn && mapEventsList) {
    footerListMapBtn.addEventListener("click", () => {
      if (mapEventsList.classList.contains("_active")) {
        mapEventsList.classList.remove("_active");
      }
    });
  }
}
document.addEventListener("DOMContentLoaded", () => {
  initSectorGroupClick();
  initResponsiveSectorMap();
});
