// Кнопка Выбрать билеты при скролле
function initStickyCartReveal() {
  const cartBox = document.querySelector('.cart-bottom__select-tickets-box');
  const targetBlock = document.querySelector('.events__body-wrapper');
  if (!cartBox || !targetBlock) return;

  // Начальные стили
  Object.assign(cartBox.style, {
    opacity: '0',
    pointerEvents: 'none',
    height: '0',
    padding: '0',
    overflow: 'hidden',
    transition: 'opacity 0.3s ease, height 0.3s ease, padding 0.3s ease'
  });
  function handleScroll() {
    if (window.innerWidth > 576) {
      hideCartBox();
      return;
    }
    const rect = targetBlock.getBoundingClientRect();
    const isVisible = rect.bottom > 0 && rect.top < window.innerHeight;
    if (isVisible) {
      hideCartBox();
    } else {
      showCartBox();
    }
  }
  function showCartBox() {
    Object.assign(cartBox.style, {
      opacity: '1',
      pointerEvents: 'auto',
      height: '',
      padding: ''
    });
  }
  function hideCartBox() {
    Object.assign(cartBox.style, {
      opacity: '0',
      pointerEvents: 'none',
      height: '0',
      padding: '0'
    });
  }
  window.addEventListener('scroll', handleScroll);
  window.addEventListener('resize', handleScroll);
  handleScroll();
}
document.addEventListener('DOMContentLoaded', initStickyCartReveal);
