function initSpartakGActiveSelection() {
  const activeGroups = document.querySelectorAll('#spartak g.active');
  const svgNS = "http://www.w3.org/2000/svg";
  function toggleSelectedClass(event) {
    const g = event.currentTarget;
    const isSelected = g.classList.toggle('selected');

    // Удаляем иконку, если есть
    const existingIcon = g.querySelector('image.check-icon');
    if (existingIcon) existingIcon.remove();
    if (isSelected) {
      addIcon(g, '../img/icons/check-w.svg');
      addHoverListeners(g);
    } else {
      removeHoverListeners(g);
    }
  }
  function addIcon(group, href) {
    const rect = group.querySelector('rect');
    if (!rect) return;
    const x = rect.getAttribute('x') || '0';
    const y = rect.getAttribute('y') || '0';
    const icon = document.createElementNS(svgNS, 'image');
    icon.setAttributeNS(null, 'href', href);
    icon.setAttributeNS(null, 'x', x);
    icon.setAttributeNS(null, 'y', y);
    icon.setAttributeNS(null, 'width', '11');
    icon.setAttributeNS(null, 'height', '11');
    icon.classList.add('check-icon');
    group.appendChild(icon);
  }
  function addHoverListeners(group) {
    group.addEventListener('mouseenter', handleMouseEnter);
    group.addEventListener('mouseleave', handleMouseLeave);
  }
  function removeHoverListeners(group) {
    group.removeEventListener('mouseenter', handleMouseEnter);
    group.removeEventListener('mouseleave', handleMouseLeave);
  }
  function handleMouseEnter(e) {
    const icon = e.currentTarget.querySelector('image.check-icon');
    if (icon) {
      icon.setAttributeNS(null, 'href', '../img/icons/close-w.svg');
    }
  }
  function handleMouseLeave(e) {
    const icon = e.currentTarget.querySelector('image.check-icon');
    if (icon) {
      icon.setAttributeNS(null, 'href', '../img/icons/check-w.svg');
    }
  }
  activeGroups.forEach(group => {
    group.addEventListener('click', toggleSelectedClass);
  });
}
document.addEventListener('DOMContentLoaded', initSpartakGActiveSelection);

