function initWindowMapFollow() {
  const map = document.querySelector('.window-map');
  const items = document.querySelectorAll('.data-map-window');
  if (!map || !items.length) return;
  items.forEach(item => {
    item.addEventListener('mouseenter', () => {
      map.classList.add('_active');
    });
    item.addEventListener('mouseleave', () => {
      map.classList.remove('_active');
    });
    item.addEventListener('mousemove', e => {
      const mapRect = map.getBoundingClientRect();

      // Получаем координаты мыши относительно viewport
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      // Позиция по горизонтали — центрируем .window-map относительно мыши
      const left = mouseX - mapRect.width / 2;

      // Позиция по вертикали — чуть выше мыши, с отступом 10px
      const top = mouseY - mapRect.height - 10;

      // Смещение с учетом прокрутки страницы
      const scrollLeft = window.pageXOffset;
      const scrollTop = window.pageYOffset;
      map.style.left = `${left + scrollLeft}px`;
      map.style.top = `${top + scrollTop}px`;
    });
  });
}
document.addEventListener('DOMContentLoaded', initWindowMapFollow);
