/** Освобождение места не изменяет запись продажи и проведённую выплату. */
window.BrokerSaleRelease = {
  submit(vm) {
    const sale = vm.releaseSale;
    if (!sale || vm.saving) {
      return;
    }
    vm.releaseError = '';
    vm.saving = true;
    const mount = document.getElementById('broker-admin-app');
    fetch('/api/controllers/brokeradmin/releaseSales/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: new URLSearchParams({
        brokerId: vm.card.broker.id,
        'saleIds[]': sale.id,
        sessid: mount ? mount.dataset.sessid : ''
      })
    }).then(response => response.json()).then(response => {
      const result = response.data;
      if (!result || !result.ok) {
        vm.releaseError = result && result.error || response.errors && response.errors[0] && response.errors[0].message || 'Не удалось освободить место';
        return;
      }
      vm.notice = 'Место освобождено. Продажа и расчёты с брокером сохранены.';
      vm.releaseSale = null;
      vm.reloadCard();
    }).catch(() => {
      vm.releaseError = 'Не удалось связаться с сервером';
    }).finally(() => {
      vm.saving = false;
    });
  }
};
