/** Учётная продажа не создаёт билет и не меняет доступность места на сайте. */
window.BrokerManualSale = {
  submit(vm) {
    const sale = vm.manualSaleForm;
    if (!sale || vm.saving) {
      return;
    }
    const required = ['order', 'event', 'eventDate', 'sector', 'row', 'seat', 'nominal', 'retail'];
    const values = {};
    const invalid = {};
    required.forEach(key => {
      values[key] = String(sale[key] ?? '').trim();
      if (!values[key]) {
        invalid[key] = true;
      }
    });
    sale.invalid = invalid;
    if (Object.keys(invalid).length) {
      sale.error = 'Заполни выделенные поля';
      return;
    }
    if (!/^[1-9]\d{0,14}$/.test(values.order)) {
      sale.invalid.order = true;
      sale.error = 'Номер заказа — от 1 до 15 цифр, без нуля в начале';
      return;
    }
    ['nominal', 'retail'].forEach(key => {
      if (!/^[1-9]\d{0,8}$/.test(values[key])) {
        sale.invalid[key] = true;
      }
    });
    if (sale.invalid.nominal || sale.invalid.retail) {
      sale.error = 'Номинал и сумма продажи — положительные целые рубли, не более 9 цифр';
      return;
    }
    sale.error = '';
    vm.saving = true;
    const mount = document.getElementById('broker-admin-app');
    const params = new URLSearchParams({
      brokerId: vm.card.broker.id,
      sessid: mount ? mount.dataset.sessid : ''
    });
    required.forEach(key => params.append(`sale[${key}]`, values[key]));
    return fetch('/api/controllers/brokeradmin/createManualSale/', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded'
      },
      body: params
    }).then(response => response.json()).then(response => {
      const result = response.data;
      if (!result || !result.ok) {
        sale.error = result && result.error || response.errors && response.errors[0] && response.errors[0].message || 'Не удалось добавить продажу';
        return;
      }
      vm.notice = result.duplicate ? 'Такая учётная продажа уже есть. Повторная строка не создана.' : 'Продажа добавлена в учёт. Долг увеличен на закупочный номинал.';
      vm.manualSaleForm = null;
      vm.reloadCard();
    }).catch(() => {
      sale.error = 'Не удалось связаться с сервером';
    }).finally(() => {
      vm.saving = false;
    });
  }
};
