// Меню "Показать Еще"
function initAdaptiveMenu() {
  const menu = document.querySelector('.menu__list');
  if (!menu) return;
  const moreItem = menu.querySelector('.menu__item._more');
  const moreSubList = moreItem?.querySelector('.menu__sub-list');
  const cartItem = [...menu.children].find(item => item.querySelector('.menu__cart'));
  if (!moreItem || !moreSubList || !cartItem) return;
  if (moreItem.nextElementSibling !== cartItem) {
    menu.insertBefore(moreItem, cartItem);
  }
  function updateMenu() {
    if (!moreSubList || !moreItem) return;

    // Вернуть все пункты из подменю назад
    const dropdownItems = moreSubList.querySelectorAll('li');
    dropdownItems.forEach(li => {
      const link = li.querySelector('a');
      if (!link) return;
      const href = link.getAttribute('href') || '#';
      const text = link.textContent.trim();
      const newItem = document.createElement('li');
      newItem.className = 'menu__item';
      newItem.innerHTML = `<a href="${href}" class="menu__link">${text}</a>`;
      menu.insertBefore(newItem, moreItem);
    });
    moreSubList.innerHTML = '';
    moreItem.style.display = 'none';
    const isMobile = window.innerWidth <= 991;
    const maxVisible = 6;
    let visibleItems;
    if (isMobile) {
      // В мобилке — максимум 6 любых пунктов
      visibleItems = [...menu.querySelectorAll('.menu__item:not(._more)')];
      if (visibleItems.length > maxVisible) {
        moreItem.style.display = 'flex';
        for (let i = visibleItems.length - 1; i >= maxVisible; i--) {
          const item = visibleItems[i];
          const link = item.querySelector('a');
          if (!link) continue;
          const href = link.getAttribute('href') || '#';
          const text = link.textContent.trim();
          const li = document.createElement('li');
          li.className = 'dropdown-list__item';
          li.innerHTML = `<a href="${href}" class="dropdown-list__link">${text}</a>`;
          moreSubList.insertBefore(li, moreSubList.firstChild);
          item.remove();
        }
      }
      return;
    }

    // Десктоп — исключаем "Еще" и "Корзину"
    const menuItems = [...menu.querySelectorAll('.menu__item:not(._more):not(:has(.menu__cart))')];
    if (menuItems.length === 0) return;
    const menuHeight = menu.getBoundingClientRect().height;
    const itemHeight = menuItems[0].getBoundingClientRect().height;
    if (menuHeight <= itemHeight + 1) return;
    moreItem.style.display = 'flex';
    let currentHeight = menu.getBoundingClientRect().height;
    for (let i = menuItems.length - 1; i >= 0; i--) {
      if (currentHeight <= itemHeight + 1 || menuItems.length <= 1) break;
      const item = menuItems[i];
      const link = item.querySelector('a');
      if (!link) continue;
      const href = link.getAttribute('href') || '#';
      const text = link.textContent.trim();
      const li = document.createElement('li');
      li.className = 'dropdown-list__item';
      li.innerHTML = `<a href="${href}" class="dropdown-list__link">${text}</a>`;
      moreSubList.insertBefore(li, moreSubList.firstChild);
      item.remove();
      currentHeight = menu.getBoundingClientRect().height;
    }
  }
  window.addEventListener('resize', () => {
    requestAnimationFrame(updateMenu);
  });
  requestAnimationFrame(() => {
    setTimeout(updateMenu, 100);
  });
}
window.addEventListener('load', () => {
  initAdaptiveMenu();
});
