// Функционал отключения выбора сертификатов
document.addEventListener("DOMContentLoaded", () => {
  const tabsContainer = document.querySelector("[data-tabs]");
  if (!tabsContainer) return;
  const updateTabStateWithoutAnimation = () => {
    const activeTabBody = tabsContainer.querySelector('[data-tabs-body] .tabs__body:not([hidden])');
    if (!activeTabBody) return;
    const giftCheckbox = activeTabBody.querySelector('input[type="checkbox"][name="form[]"][id^="check-sk"]');
    const quantityButtons = activeTabBody.querySelectorAll(".quantity__button");
    const giftEmailField = activeTabBody.querySelector('[data-gift-email]');
    if (!giftCheckbox) return;

    // Обновляем кнопки
    const disableButtons = giftCheckbox.checked;
    quantityButtons.forEach(btn => {
      btn.disabled = disableButtons;
      btn.classList.toggle("quantity__button_disabled", disableButtons);
    });

    // Без анимации: просто показать или скрыть поле Email
    if (giftEmailField) {
      if (giftCheckbox.checked) {
        giftEmailField.hidden = false;
      } else {
        giftEmailField.hidden = true;
      }
    }
  };
  const handleCheckboxToggle = checkbox => {
    const activeTabBody = tabsContainer.querySelector('[data-tabs-body] .tabs__body:not([hidden])');
    if (!activeTabBody) return;
    const giftEmailField = activeTabBody.querySelector('[data-gift-email]');
    const quantityButtons = activeTabBody.querySelectorAll(".quantity__button");
    if (!giftEmailField || !checkbox) return;

    // Обновляем кнопки
    const disableButtons = checkbox.checked;
    quantityButtons.forEach(btn => {
      btn.disabled = disableButtons;
      btn.classList.toggle("quantity__button_disabled", disableButtons);
    });

    // Только при клике — с анимацией
    if (typeof _slideToggle === 'function') {
      _slideToggle(giftEmailField, 300);
    }
  };

  // Переключение табов — без анимации
  const tabButtons = tabsContainer.querySelectorAll("[data-tabs-titles] .tabs__title");
  tabButtons.forEach(btn => {
    btn.addEventListener("click", () => {
      requestAnimationFrame(updateTabStateWithoutAnimation);
    });
  });

  // Клик по чекбоксу — с анимацией
  tabsContainer.addEventListener("change", e => {
    if (e.target && e.target.matches('input[type="checkbox"][name="form[]"][id^="check-sk"]')) {
      handleCheckboxToggle(e.target);
    }
  });

  // Первая инициализация — без анимации
  updateTabStateWithoutAnimation();
});

