// Множественный выбор
function updateSelectTagsByLineBreak(selectBody) {
  const content = selectBody.querySelector('.select__content');
  if (!content) return;
  const tags = Array.from(content.querySelectorAll('._select-tag:not(._select-tag-plus)'));
  if (tags.length <= 2) {
    const plusTag = content.querySelector('._select-tag._select-tag-plus');
    if (plusTag) plusTag.remove();
    tags.forEach(tag => tag.style.display = '');
    return;
  }

  // Сначала показываем все теги для правильного расчета позиций
  tags.forEach(tag => tag.style.display = '');

  // Принудительно вызываем пересчет layout
  content.offsetHeight;

  // Проверяем ширину контейнера и тегов
  const containerWidth = content.offsetWidth;
  const containerHeight = content.offsetHeight;

  // Если контейнер имеет высоту больше одной строки, значит есть переполнение
  const singleLineHeight = tags[0] ? tags[0].offsetHeight : 0;
  const hasOverflow = containerHeight > singleLineHeight * 1.5; // Небольшой запас

  if (!hasOverflow) {
    const plusTag = content.querySelector('._select-tag._select-tag-plus');
    if (plusTag) plusTag.remove();
    return;
  }

  // Определяем, сколько тегов помещается в первую строку
  let firstLineTags = [];
  let currentWidth = 0;
  const maxWidth = containerWidth - 60; // Оставляем место для +N тега

  for (const tag of tags) {
    const tagWidth = tag.offsetWidth + 4; // Учитываем margin-right

    // Если даже один тег не помещается, показываем только первые 2
    if (tagWidth > maxWidth) {
      firstLineTags = tags.slice(0, 2);
      break;
    }
    if (currentWidth + tagWidth <= maxWidth) {
      firstLineTags.push(tag);
      currentWidth += tagWidth;
    } else {
      break;
    }
  }

  // Если все теги поместились в одну строку, убираем +N
  if (firstLineTags.length === tags.length) {
    const plusTag = content.querySelector('._select-tag._select-tag-plus');
    if (plusTag) plusTag.remove();
    return;
  }

  // Показываем только первые теги, остальные скрываем
  tags.forEach(tag => tag.style.display = 'none');
  firstLineTags.forEach(tag => tag.style.display = '');
  const hiddenCount = tags.length - firstLineTags.length;
  let plusTag = content.querySelector('._select-tag._select-tag-plus');
  if (!plusTag) {
    plusTag = document.createElement('span');
    plusTag.className = '_select-tag _select-tag-plus';
    plusTag.setAttribute('role', 'button');
    content.appendChild(plusTag);
  }
  plusTag.textContent = `+${hiddenCount}`;
  plusTag.style.display = '';
}
function watchSelect(selectBody) {
  // Создаём наблюдатель за изменениями внутри .select__content
  const content = selectBody.querySelector('.select__content');
  if (!content) return;

  // Слушаем изменения в самом select__content с помощью MutationObserver
  const observer = new MutationObserver(mutations => {
    let shouldUpdate = false;
    mutations.forEach(mutation => {
      if (mutation.type === 'childList') {
        shouldUpdate = true;
      }
    });
    if (shouldUpdate) {
      setTimeout(() => {
        forceCheckAndCollectTags();
        updateSelectTagsByLineBreak(selectBody);
      }, 10);
    }
  });

  // Начинаем наблюдение за изменениями в content
  observer.observe(content, {
    childList: true,
    subtree: true
  });

  // Также слушаем клики по кнопкам внутри select__options
  const options = selectBody.querySelector('.select__options');
  if (options) {
    options.addEventListener('click', e => {
      // Можно отфильтровать, если надо — проверяем целевой элемент
      if (e.target.classList.contains('select__option')) {
        // Задержка чтобы все изменения DOM произошли, затем обновляем
        setTimeout(() => {
          forceCheckAndCollectTags();
          updateSelectTagsByLineBreak(selectBody);
        }, 50);
      }
    });
  }

  // И сразу запускаем обновление один раз при старте
  updateSelectTagsByLineBreak(selectBody);
}
function initAllSelects() {
  document.querySelectorAll('.select__body').forEach(watchSelect);
}

// Запускаем и при загрузке страницы
window.addEventListener('load', initAllSelects);
// И при ресайзе

// Дополнительная инициализация для Vue компонентов
document.addEventListener('DOMContentLoaded', () => {
  // Проверяем Vue компоненты каждые 500ms в течение первых 5 секунд
  let checkCount = 0;
  const checkVueSelects = () => {
    if (checkCount < 10) {
      document.querySelectorAll('.select__body').forEach(watchSelect);
      checkCount++;
      setTimeout(checkVueSelects, 500);
    }
  };
  setTimeout(checkVueSelects, 1000);
});
window.addEventListener('resize', () => {
  document.querySelectorAll('.select__body').forEach(updateSelectTagsByLineBreak);
});

// После определения функции updateSelectTagsByLineBreak
function forceUpdateAllSelectTags() {
  document.querySelectorAll('.select__body').forEach(updateSelectTagsByLineBreak);
}

// Функция для принудительной проверки и сбора тегов
function forceCheckAndCollectTags() {
  document.querySelectorAll('.select__body').forEach(selectBody => {
    const content = selectBody.querySelector('.select__content');
    if (!content) return;
    const tags = Array.from(content.querySelectorAll('._select-tag:not(._select-tag-plus)'));
    if (tags.length <= 2) return;

    // Показываем все теги для проверки
    tags.forEach(tag => tag.style.display = '');

    // Принудительно вызываем пересчет layout
    content.offsetHeight;

    // Проверяем, есть ли теги на второй строке
    const firstTop = tags[0].offsetTop;
    let hasSecondLine = false;
    for (const tag of tags) {
      if (tag.offsetTop > firstTop) {
        hasSecondLine = true;
        break;
      }
    }

    // Если есть вторая строка, принудительно собираем теги
    if (hasSecondLine) {
      updateSelectTagsByLineBreak(selectBody);
    }
  });
}

// Обновляем теги при открытии любого селекта
// (чтобы после анимаций и появления новых размеров всё считалось корректно)
document.addEventListener('click', e => {
  if (e.target.closest('.select__title')) {
    setTimeout(forceUpdateAllSelectTags, 50); // небольшая задержка для анимации
  }
});

// Дополнительный обработчик для мультиселектов
document.addEventListener('click', e => {
  // Проверяем клики по опциям мультиселектов
  if (e.target.classList.contains('select__option')) {
    // Немедленная проверка + принудительная проверка перестроения
    forceUpdateAllSelectTags();
    setTimeout(() => {
      forceCheckAndCollectTags();
      forceUpdateAllSelectTags();
    }, 50);
    setTimeout(() => {
      forceCheckAndCollectTags();
      forceUpdateAllSelectTags();
    }, 150);
  }

  // Проверяем клики по тегам (удаление тегов)
  if (e.target.classList.contains('_select-tag') && !e.target.classList.contains('_select-tag-plus')) {
    setTimeout(() => {
      forceCheckAndCollectTags();
      forceUpdateAllSelectTags();
    }, 100);
  }
});

// Обработчик для изменений в мультиселектах
document.addEventListener('change', e => {
  if (e.target.matches('select[multiple]')) {
    setTimeout(() => {
      forceCheckAndCollectTags();
      forceUpdateAllSelectTags();
    }, 100);
  }
});
