document.addEventListener('DOMContentLoaded', function () {
  const radios = document.querySelectorAll('.box-order__options-input');
  const addressField = document.getElementById('address-field');
  radios.forEach(radio => {
    radio.addEventListener('change', function () {
      const isCard = radio.closest('.box-order').querySelector('.box-order__options-descp-title')?.textContent.includes('Банковской картой');
      if (addressField && typeof _slideToggle === 'function') {
        if (isCard && radio.checked) {
          // Показать адрес
          _slideToggle(addressField, 500, true);
        } else if (radio.checked) {
          // Скрыть адрес
          _slideToggle(addressField, 500, false);
        }
      }
    });
  });
});

