document.addEventListener("DOMContentLoaded", function () {
  const cards = document.querySelectorAll(".card-list-map");
  cards.forEach(card => {
    const button = card.querySelector(".card-list-map__btn");
    const submenu = card.querySelector(".card-list-map__submenu");
    if (button && submenu) {
      button.addEventListener("click", function () {
        // переключаем класс _active
        button.classList.toggle("_active");

        // меняем текст кнопки
        if (button.classList.contains("_active")) {
          button.firstChild.textContent = "Свернуть";
        } else {
          button.firstChild.textContent = "Открыть сектор";
        }

        // плавное открытие/закрытие подменю
        if (typeof _slideToggle === "function") {
          _slideToggle(submenu, 500);
        }
      });
    }
  });
});
