document.addEventListener("DOMContentLoaded", () => {
  const choiceTicketsBtn = document.querySelector(".choice-tickets__btn");
  const schemeBox = document.querySelector(".map-events__map-scheme-box");
  const sectorsBlock = document.querySelector(".map-events__sectors");
  const schemeHeaderBtnCl = document.querySelector(".js-scheme-map-close");
  const jsListMapBtnCl = document.querySelector(".js-list-map-close");
  const sectorsMapBtnCl = document.querySelector(".sectors-map__btn-close-mob");
  const mapEventsList = document.querySelector(".map-events__list");
  if (choiceTicketsBtn && schemeBox) {
    choiceTicketsBtn.addEventListener("click", () => {
      if (window.innerWidth <= 1024) {
        schemeBox.classList.add("_active");
        schemeBox.removeAttribute("hidden");
        bodyLockToggle();
      }
    });
  }
  if (schemeHeaderBtnCl && schemeBox && sectorsBlock) {
    schemeHeaderBtnCl.addEventListener("click", () => {
      schemeBox.classList.remove("_active");
      mapEventsList.classList.remove("_active");
      sectorsBlock.classList.remove("_active");
      bodyLockToggle();
    });
  }
  if (sectorsMapBtnCl && schemeBox && sectorsBlock) {
    sectorsMapBtnCl.addEventListener("click", () => {
      schemeBox.classList.remove("_active");
      sectorsBlock.classList.remove("_active");
      bodyLockToggle();
    });
  }

  // Обработчик для кнопки закрытия списка событий
  if (jsListMapBtnCl && schemeBox && mapEventsList && sectorsBlock) {
    jsListMapBtnCl.addEventListener("click", () => {
      schemeBox.classList.remove("_active");
      mapEventsList.classList.remove("_active");
      sectorsBlock.classList.remove("_active");
      bodyLockToggle();
    });
  }
});
document.addEventListener('DOMContentLoaded', function () {
  // BEGIN ->ВЫРАВНИВАЮ ПО ВЫСОТЕ ПУНКТЫ СПИСКА ПРЕИМУЩЕСТВ НА ГЛАВНОЙ СТРАНИЦЕ 
  if (window.location.pathname === '/' || window.location.pathname === '../../../../../../../index.html') {
    // Получаем оба списка
    const leftList = document.getElementById('item-advantages__list_l');
    const rightList = document.getElementById('item-advantages__list_r');

    // Получаем все элементы <li> из обоих списков
    const leftItems = leftList.querySelectorAll('.list-advantages__item');
    const rightItems = rightList.querySelectorAll('.list-advantages__item');

    // Проверяем, что количество элементов совпадает
    if (leftItems.length !== rightItems.length) {
      console.warn('Количество элементов в списках не совпадает!');
    }

    // Проходим по каждой паре элементов
    for (let i = 0; i < leftItems.length; i++) {
      const leftItem = leftItems[i];
      const rightItem = rightItems[i];

      // Сбрасываем высоту (на случай, если она уже была задана)
      leftItem.style.height = 'auto';
      rightItem.style.height = 'auto';

      // Получаем высоты элементов
      const leftHeight = leftItem.offsetHeight;
      const rightHeight = rightItem.offsetHeight;

      // Выбираем максимальную высоту
      const maxHeight = Math.max(leftHeight, rightHeight);

      // Устанавливаем максимальную высоту обоим элементам
      leftItem.style.height = `${maxHeight}px`;
      rightItem.style.height = `${maxHeight}px`;
    }
  }
  // END ->ВЫРАВНИВАЮ ПО ВЫСОТЕ ПУНКТЫ СПИСКА ПРЕИМУЩЕСТВ НА ГЛАВНОЙ СТРАНИЦЕ

  // BEGIN ->СНИМАЮ ВЫДЕЛЕНИЕ ОШИБКИ ПРИ КЛИКЕ НА ГАЛКУ СОГЛАСИЕМ 
  const labels = document.querySelectorAll('label.form__checkbox.checkbox');
  labels.forEach(label => {
    label.addEventListener('click', function () {
      if (this.classList.contains('_form-error')) {
        this.classList.remove('_form-error');
      }
    });
  });
  // END ->СНИМАЮ ВЫДЕЛЕНИЕ ОШИБКИ ПРИ КЛИКЕ НА ГАЛКУ СОГЛАСИЕМ 

  // BEGIN ->ИНИЦИАЛИЗИРУЮ БОКОВОЕ МЕНЮ
  if (typeof SideMenu === 'undefined') console.error('❌ SideMenu не определён');else SideMenu.init();
  // END ->ИНИЦИАЛИЗИРУЮ БОКОВОЕ МЕНЮ
});

