/**
 * Универсальный инициализатор Яндекс SmartCaptcha (невидимая) для форм
 * Использование: добавьте атрибут data-captcha="true" к любой форме
 *
 * @version 3.0 (ленивый рендер: виджет создаётся при первом взаимодействии с формой)
 */
(function () {
  'use strict';

  const arCaptchaInstances = new Map();
  const arFailedForms = new WeakSet();
  let arPendingForms = [];
  let nCheckInterval = null;

  /**
   * Инициализация капчи для формы
   * @param {HTMLFormElement} obForm
   */
  function initCaptchaForForm(obForm) {
    // Виджет для этой формы уже создан
    if (obForm.captchaAPI) {
      return;
    }

    // render() для этой формы уже падал — не повторяем попытку на каждое взаимодействие
    if (arFailedForms.has(obForm)) {
      return;
    }
    if (typeof window.smartCaptcha === 'undefined') {
      if (!arPendingForms.includes(obForm)) {
        arPendingForms.push(obForm);
      }
      startApiWatcher();
      return;
    }
    const sCaptchaId = obForm.id || 'form-' + Math.random().toString(36).substr(2, 9);
    if (arCaptchaInstances.has(sCaptchaId)) {
      return;
    }
    const obCaptchaContainer = obForm.querySelector('.smart-captcha');
    if (!obCaptchaContainer) {
      console.warn('[Captcha] Контейнер .smart-captcha не найден в форме', obForm);
      return;
    }
    let bCaptchaExecuted = false;
    let sCurrentToken = '';
    let nWidgetId = null;
    let fnPendingSubmit = null;
    try {
      nWidgetId = window.smartCaptcha.render(obCaptchaContainer, {
        sitekey: obCaptchaContainer.getAttribute('data-sitekey'),
        invisible: true,
        shieldPosition: 'bottom-left',
        hideShield: true,
        callback: function (sToken) {
          bCaptchaExecuted = true;
          sCurrentToken = sToken;
          let obTokenInput = obForm.querySelector('input[name="smart-token"]');
          if (!obTokenInput) {
            obTokenInput = document.createElement('input');
            obTokenInput.type = 'hidden';
            obTokenInput.name = 'smart-token';
            obForm.appendChild(obTokenInput);
          }
          obTokenInput.value = sToken;
          obForm.dispatchEvent(new CustomEvent('captchaSuccess', {
            detail: {
              token: sToken,
              formId: sCaptchaId
            }
          }));
          if (fnPendingSubmit) {
            fnPendingSubmit();
            fnPendingSubmit = null;
          }
        },
        'expired-callback': function () {
          bCaptchaExecuted = false;
          sCurrentToken = '';
          const obTokenInput = obForm.querySelector('input[name="smart-token"]');
          if (obTokenInput) {
            obTokenInput.value = '';
          }
        }
      });
    } catch (e) {
      // render() бросил исключение (невалидный ключ, API в плохом состоянии и т.п.)
      // Форма остаётся без captchaAPI — formSubmit пропустит блок капчи и отправит форму
      console.error('[Captcha] Ошибка render() для формы:', sCaptchaId, e);
      arFailedForms.add(obForm);
      return;
    }
    const obCaptchaAPI = {
      form: obForm,
      container: obCaptchaContainer,
      widgetId: nWidgetId,
      isExecuted: function () {
        return bCaptchaExecuted;
      },
      getToken: function () {
        return sCurrentToken;
      },
      reset: function () {
        bCaptchaExecuted = false;
        sCurrentToken = '';
        fnPendingSubmit = null;
        const obTokenInput = obForm.querySelector('input[name="smart-token"]');
        if (obTokenInput) {
          obTokenInput.value = '';
        }
        try {
          if (nWidgetId !== null) window.smartCaptcha.reset(nWidgetId);
        } catch (e) {
          console.warn('[Captcha] Ошибка reset():', e);
        }
      },
      execute: function (fnCallback) {
        if (fnCallback) fnPendingSubmit = fnCallback;
        try {
          window.smartCaptcha.execute(nWidgetId);
        } catch (e) {
          // execute() упал — вызываем колбэк сразу, чтобы не заморозить форму
          // Токен будет пустым, сервер обработает это согласно своей fail-open политике
          console.error('[Captcha] Ошибка execute() для формы:', sCaptchaId, e);
          fnPendingSubmit = null;
          if (fnCallback) fnCallback(null);
        }
      }
    };
    arCaptchaInstances.set(sCaptchaId, obCaptchaAPI);
    obForm.captchaAPI = obCaptchaAPI;
  }
  function initAllCaptchaForms() {
    const arForms = document.querySelectorAll('form[data-captcha="true"]');
    arForms.forEach(initCaptchaForForm);
  }
  function processPendingForms() {
    if (arPendingForms.length > 0) {
      const formsToInit = [...arPendingForms];
      arPendingForms = [];
      formsToInit.forEach(initCaptchaForForm);
    }
  }

  /**
   * Ожидание загрузки API Яндекса. Запускается только когда есть отложенные формы,
   * то есть пользователь уже начал взаимодействие, а captcha.js ещё не догрузился.
   */
  function startApiWatcher() {
    if (nCheckInterval !== null) {
      return;
    }
    nCheckInterval = setInterval(function () {
      if (typeof window.smartCaptcha !== 'undefined') {
        stopApiWatcher();
        processPendingForms();
      }
    }, 100);
    setTimeout(function () {
      if (nCheckInterval !== null) {
        stopApiWatcher();
        if (arPendingForms.length > 0) {
          console.error('[Captcha] API не загрузился за 10 секунд');
        }
      }
    }, 10000);
  }
  function stopApiWatcher() {
    clearInterval(nCheckInterval);
    nCheckInterval = null;
  }

  /**
   * Первое взаимодействие с формой — момент создания виджета
   * @param {Event} obEvent
   */
  function onFormInteraction(obEvent) {
    const obTarget = obEvent.target;
    if (!obTarget || typeof obTarget.closest !== 'function') {
      return;
    }
    const obForm = obTarget.closest('form[data-captcha="true"]');
    if (obForm) {
      initCaptchaForForm(obForm);
    }
  }

  // Слушатели на capture-фазе document.
  // Для submit это принципиально: обработчик отправки в forms.js висит на самой форме,
  // а capture на document срабатывает раньше — значит form.captchaAPI будет создан
  // до чтения. Иначе форма ушла бы без поля smart-token, и PHP заблокировал бы её как бота.
  document.addEventListener('focusin', onFormInteraction, true);
  document.addEventListener('pointerdown', onFormInteraction, true);
  document.addEventListener('submit', onFormInteraction, true);
  window.YandexCaptchaAPI = {
    getFormCaptcha: function (formIdOrElement) {
      const sFormId = typeof formIdOrElement === 'string' ? formIdOrElement : formIdOrElement.id;
      return arCaptchaInstances.get(sFormId) || null;
    },
    initForm: initCaptchaForForm,
    reinitAll: initAllCaptchaForms,
    debug: {
      getInstances: () => arCaptchaInstances,
      getPending: () => arPendingForms
    }
  };
})();
